function bestSplitProduct(n: number): number {
  const best = new Array(n + 1).fill(0);
  best[1] = 1;
  for (let k = 2; k <= n; k++) {
    for (let j = 1; j < k; j++) {
      best[k] = Math.max(best[k], j * Math.max(k - j, best[k - j]));
    }
  }
  return best[n];
}

